"""The static demo build: deterministic, generated by the real runtime, host-agnostic."""
import json
import re
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tools"))
import build_demo  # noqa: E402

SECONDS = 20.0


@pytest.fixture(scope="module")
def built(tmp_path_factory):
    out = tmp_path_factory.mktemp("demo")
    build_demo.build(out / "a", 7, "demo", SECONDS)
    build_demo.build(out / "b", 7, "demo", SECONDS)
    return out


def test_two_builds_are_byte_identical(built):
    names = sorted(p.name for p in (built / "a").iterdir())
    assert names == sorted(p.name for p in (built / "b").iterdir())
    for name in names:
        assert (built / "a" / name).read_bytes() == (built / "b" / name).read_bytes(), name


def test_expected_files(built):
    assert {p.name for p in (built / "a").iterdir()} == {
        "index.html", "recording.json", "style.css", "view3d.js", "app.js", "demo.js"}


def test_frames_match_live_ws_payload(built, tmp_path):
    from wallhack.config import Config
    from wallhack.runtime import Runtime
    rec = json.loads((built / "a" / "recording.json").read_text())
    assert len(rec["frames"]) == int(SECONDS / build_demo.TICK_S)
    live = Runtime(Config(source="simulator", scenario="demo", seed=7, background=False))
    live.step_sim(5)
    first = rec["frames"][0]
    assert set(first) == {"status", "zones", "links", "samples", "events"}
    assert set(first["status"]) == set(live.status())
    assert first["status"]["vitals"].keys() == live.vitals().keys()
    assert first["status"]["environment"]["simulated"] is not None or first["status"]["environment"]
    seqs = [s["seq"] for f in rec["frames"] for s in f["samples"]]
    assert seqs == list(range(1, len(seqs) + 1))


def test_static_host_safe_index(built):
    html = (built / "a" / "index.html").read_text()
    assert not re.search(r'(?:src|href)="/', html)
    assert html.index("demo.js") < html.index("view3d.js") < html.index("app.js")
    for ref in re.findall(r'(?:src|href)="([^"]+)"', html):
        assert (built / "a" / ref).is_file(), ref
    assert "cannot literally see through walls" in html and "SIMULATED" in html
    demo = (built / "a" / "demo.js").read_text()
    assert "Simulated replay. Not live sensing" in demo
    assert "/ws" not in demo


def test_build_script_runs_without_fastapi(tmp_path):
    code = ("import sys\nfor m in ('fastapi','uvicorn','starlette','pydantic'): sys.modules[m] = None\n"
            "import runpy\nsys.argv = ['build_demo.py', '--seconds', '2', '--out', %r]\n"
            "runpy.run_path(%r, run_name='__main__')" % (str(tmp_path / "o"), str(ROOT / "tools" / "build_demo.py")))
    r = subprocess.run([sys.executable, "-c", code], capture_output=True, text=True, cwd=ROOT)
    assert r.returncode == 0, r.stderr
    assert (tmp_path / "o" / "recording.json").is_file()


def test_vercel_config():
    cfg = json.loads((ROOT / "vercel.json").read_text())
    assert cfg["outputDirectory"] == "dist"
    assert "tools/build_demo.py" in cfg["buildCommand"]
    csp = next(h["value"] for e in cfg["headers"] for h in e["headers"] if h["key"] == "Content-Security-Policy")
    assert "default-src 'self'" in csp and "connect-src 'self'" in csp
    assert "dist/" in (ROOT / ".gitignore").read_text().split()
